def ex(text, W=40):
    verbs=('save','write','writes','create','creates','output','outputs','produce','produces','store','stores','generate','generates','place','put','emit')
    low=text.lower(); PATH=re.compile(r'(/[A-Za-z0-9_][A-Za-z0-9_./+-]*)')
    out=[]
    for m in PATH.finditer(text):
        p=m.group(1).rstrip('.,;:)]}\'\"')
        if len(p)<3 or p.endswith('/'): continue
        w=low[max(0,m.start(1)-W):m.start(1)]
